import {Vector2} from 'three'
import type Common from './common'
import {getScaleDelta} from './utils/math'

export default class MouseMng {
  originalPos: Vector2
  mousemoveFuncs: Array<() => void>
  pos: {target: Vector2; current: Vector2; current2: Vector2}
  common?: Common
  constructor(common: Common) {
    this.common = common
    this.originalPos = new Vector2()

    this.mousemoveFuncs = []
    this.pos = {
      target: new Vector2(0, 0),
      current: new Vector2(0, 0),
      current2: new Vector2(0, 0),
    }

    this.init()
  }

  init() {
    window.addEventListener('mousemove', event => {
      if (!this.common) return
      let x = (event.clientX - this.common?.wrapperOffset.x + this.common?.copilotAreaOffset.x) / this.common?.sizes.x
      x = (x - 0.5) * 2.0
      let y = (event.clientY - this.common?.wrapperOffset.y + this.common?.copilotAreaOffset.y) / this.common?.sizes.y
      y = (0.5 - y) * 2.0

      x = Math.max(-1, Math.min(1, x))
      y = Math.max(-1, Math.min(1, y))

      this.updateMousePos(x, y)
    })

    // eslint-disable-next-line github/require-passive-events
    window.addEventListener('touchstart', event => {
      if (!this.common) return
      if (event.touches[0]) {
        let x =
          (event.touches[0].clientX - this.common?.wrapperOffset.x + this.common?.copilotAreaOffset.x) /
          this.common?.sizes.x
        x = (x - 0.5) * 2.0
        let y =
          (event.touches[0].clientY - this.common?.wrapperOffset.y + this.common?.copilotAreaOffset.y) /
          this.common?.sizes.y
        y = (0.5 - y) * 2.0

        this.updateMousePos(x, y)
      }
    })
  }

  updateMousePos(x: number, y: number) {
    this.pos.target.set(x, y)

    for (const func of this.mousemoveFuncs) {
      func()
    }
  }

  addMousemoveFunc(func: () => void) {
    this.mousemoveFuncs.push(func)
  }

  resize() {}

  update() {
    if (!this.common) return
    this.pos.current.lerp(this.pos.target, getScaleDelta(2, this.common.delta))
    this.pos.current2.lerp(this.pos.target, getScaleDelta(1.5, this.common.delta))
  }
}
