import Animations from './animations'
import type {Mesh, Texture} from 'three'
import {Group, MeshMatcapMaterial, Raycaster, Vector3} from 'three'
import vertexShader from './shaders/mesh'
import fragmentShader from './shaders/matcap'
import type MouseMng from './mouseMng'
import type Common from './common'
import type AssetsCta from './assets'
import {getScaleDelta, getProgress, lerp} from './utils/math'

export default class CopilotHead {
  group: Group
  orientationGroup: Group
  animationGroup: Group
  goggleGroup: Group
  faceGroup: Group
  eyesMeshes: {left: Mesh | null; right: Mesh | null}
  breathing: {rotation: number; position: number}
  lookatTarget: Vector3 = new Vector3(0, 0, 0)
  lookatTarget2: Vector3 = new Vector3(0, 0, 0)
  lookatTargetProgress: number = 0
  lookatTarget_default: Vector3 = new Vector3(0, 0, 1.0)
  raycaster: Raycaster
  isRaycastHit: boolean
  mouseIntensity: {target: number; current: number}
  uniforms: {fresnelBias: {value: number}; fresnelScale: {value: number}; fresnelPower: {value: number}}
  animations: Animations
  common: Common
  assets: AssetsCta
  mouseMng: MouseMng

  constructor(common: Common, assets: AssetsCta, mouseMng: MouseMng) {
    this.mouseMng = mouseMng
    this.common = common
    this.assets = assets
    this.group = new Group()

    this.orientationGroup = new Group()
    this.animationGroup = new Group()

    this.group.add(this.orientationGroup)
    this.orientationGroup.add(this.animationGroup)

    this.goggleGroup = new Group()
    this.faceGroup = new Group()
    this.animationGroup.add(this.goggleGroup)
    this.animationGroup.add(this.faceGroup)
    this.eyesMeshes = {
      left: null,
      right: null,
    }

    this.breathing = {
      rotation: 0.0,
      position: 0.0,
    }

    this.goggleGroup.userData.rotateX = {
      orientation: 0,
      anim_rotating: 0,
    }

    this.raycaster = new Raycaster()
    this.isRaycastHit = false
    this.mouseIntensity = {
      target: 0,
      current: 0,
    }

    this.uniforms = {
      fresnelBias: {
        value: 0.01,
      },
      fresnelScale: {
        value: 2.0,
      },
      fresnelPower: {
        value: 3.0,
      },
    }

    this.common.scene.add(this.group)
  }

  init() {
    this.addMeshes()
    this.createAnimations()
  }

  addMeshes() {
    const meshes: Array<{object: Mesh; isGoggle?: boolean; isFace?: boolean}> = []
    if (!this.assets.gltfs.head.scene) return

    this.assets.gltfs.head.scene.traverse(mesh => {
      const object: Mesh = mesh as Mesh
      if (object.isMesh) {
        let texture
        switch (object.name) {
          case 'Goggle':
          case 'LeftEye':
          case 'RightEye':
          case 'Glass001':
            texture = this.assets.images.bakedGoggle.texture
            break
          case 'HeadBase':
            texture = this.assets.images.bakedHead.texture
            break
          case 'Screen':
            texture = this.assets.images.bakedOther.texture
            break
        }
        const isFresnel = object.name === 'HeadBase'

        const isEye = object.name === 'RightEye' || object.name === 'LeftEye'
        const fresnelGamma = object.name === 'Goggle' ? 0.9 : 0.5
        object.material = this.createMaterial(texture, isFresnel, isEye, fresnelGamma)

        switch (object.name) {
          case 'Goggle':
          case 'Glass001':
            meshes.push({
              object,
              isGoggle: true,
            })
            break
          default:
            meshes.push({
              object,
              isFace: true,
            })
            break
        }

        if (object.name === 'RightEye') {
          this.eyesMeshes.right = object
        } else if (object.name === 'LeftEye') {
          this.eyesMeshes.left = object
        }
      }
    })

    for (const item of meshes) {
      const object = item.object
      if (object.parent) object.parent.remove(object)
      if (item.isGoggle) this.goggleGroup.add(object)
      if (item.isFace) this.faceGroup.add(object)
    }
  }

  createMaterial(bakedTexture: Texture | null | undefined, isFresnel: boolean, isEye: boolean, fresnelGamma: number) {
    /**
     * Materials
     */

    //Main Matcap Material
    // bakedMaterial.isMeshMatcapMaterial = true;
    const dynamicUniforms = {
      uWink: {
        value: 0,
      },
    }
    const material = new MeshMatcapMaterial({
      map: bakedTexture,
      matcap: this.assets.images.matcap.texture,
      transparent: true, // Enable alpha blending
    })

    material.onBeforeCompile = shader => {
      shader.uniforms = {
        ...shader.uniforms,
        ...this.uniforms,
        uFresnelIntensity: {
          value: isFresnel ? 1 : 0,
        },
        uIsEye: {
          value: isEye,
        },
        uFresnelGamma: {
          value: fresnelGamma,
        },
        ...dynamicUniforms,
      }

      shader.vertexShader = vertexShader
      shader.fragmentShader = fragmentShader
    }
    material.userData.uniforms = dynamicUniforms
    return material
  }

  createAnimations() {
    this.animations = new Animations({
      animationGroup: this.animationGroup,
      goggleGroup: this.goggleGroup,
      eyesMeshes: this.eyesMeshes,
      common: this.common,
    })

    this.mouseMng.addMousemoveFunc(this.raycast.bind(this))

    // document.body.addEventListener('click', () => {
    //   if (this.isRaycastHit) {
    //     this.animations.createClickAnimation()
    //   }
    // })
  }

  doHappyReaction() {
    this.animations.createClickAnimation()
  }

  raycast() {
    this.raycaster.setFromCamera(this.mouseMng.pos.target, this.common.camera)
    const intersects = this.raycaster.intersectObject(this.group)

    if (intersects.length > 0) {
      this.isRaycastHit = true
    } else {
      this.isRaycastHit = false
    }
  }

  update() {
    this.breathing.rotation = Math.sin(this.common.time * 2) * 0.05
    this.breathing.position = Math.sin((this.common.time + 0.25) * 2) * 0.08

    const mouseLength = this.mouseMng.pos.target.length()

    this.mouseIntensity.target = getProgress(2, 1.0, mouseLength)
    this.mouseIntensity.current +=
      (this.mouseIntensity.target - this.mouseIntensity.current) * getScaleDelta(3, this.common.delta)

    this.lookatTarget.set(this.mouseMng.pos.current.x * 0.6, this.mouseMng.pos.current.y * 0.6, 1)
    this.lookatTarget.lerp(this.lookatTarget_default, 1 - this.mouseIntensity.current)
    this.lookatTarget.y += this.breathing.rotation

    if (this.animations?.isPlayingClickAnim) {
      this.lookatTargetProgress += (1 - this.lookatTargetProgress) * getScaleDelta(3, this.common.delta)
    } else {
      this.lookatTargetProgress += (0 - this.lookatTargetProgress) * getScaleDelta(3, this.common.delta)
    }

    this.lookatTarget2
      .set(this.lookatTarget.x, 0, this.lookatTarget.z)
      .lerp(this.lookatTarget, 1.0 - this.lookatTargetProgress)
    this.lookatTarget2.y += this.group.position.y

    this.orientationGroup.lookAt(this.lookatTarget2)
    this.orientationGroup.position.y = this.breathing.position

    let goggleRotateXProgress = getProgress(0.0, 0.5, this.mouseMng.pos.current2.y)
    goggleRotateXProgress = lerp(0, goggleRotateXProgress, this.mouseIntensity.current)
    goggleRotateXProgress += (this.breathing.rotation + 1.0) * 1.2
    goggleRotateXProgress = Math.min(goggleRotateXProgress, 1.0)
    this.goggleGroup.userData.rotateX.orientation = lerp(0.1, -0.08, goggleRotateXProgress)

    this.goggleGroup.rotation.x = 0

    for (const key in this.goggleGroup.userData.rotateX) {
      const value = this.goggleGroup.userData.rotateX[key]
      this.goggleGroup.rotation.x += value
    }
  }

  resize(scale: number) {
    this.group.position.y = scale * this.common.copilotAreaOffset.y
  }
}
