import type {Scene} from 'three'
import {sRGBEncoding, TextureLoader} from 'three'
import {GLTFLoader} from 'three/examples/jsm/loaders/GLTFLoader'

interface Image {
  src: string
  texture: null
  flipY: boolean
  encoding?: number
}

interface Images {
  bakedGoggle: Image
  bakedHead: Image
  bakedOther: Image
  matcap: Image
  starShape: Image
  starShapeGlow: Image
  starShapeShadow: Image
}

interface gltf {
  src: string
  scene: Scene | null
}

interface gltfs {
  head: gltf
}
const imagePath = '/images/modules/site/lab/'

export default class Assets {
  images: Images = {
    bakedGoggle: {
      src: `${imagePath}bakedGoggle.png`,
      texture: null,
      flipY: false,
      encoding: sRGBEncoding,
    },
    bakedHead: {
      src: `${imagePath}bakedHead.png`,
      texture: null,
      flipY: false,
      encoding: sRGBEncoding,
    },
    bakedOther: {
      src: `${imagePath}bakedOther.png`,
      texture: null,
      flipY: false,
      encoding: sRGBEncoding,
    },
    matcap: {
      src: `${imagePath}matcap.png`,
      texture: null,
      flipY: true,
    },
    starShape: {
      src: `${imagePath}star-shape.jpg`,
      texture: null,
      flipY: false,
    },
    starShapeShadow: {
      src: `${imagePath}star-shape-shadow.jpg`,
      texture: null,
      flipY: false,
    },
    starShapeGlow: {
      src: `${imagePath}star-shape-glow.jpg`,
      texture: null,
      flipY: false,
    },
  }
  gltfs: gltfs = {
    head: {
      src: `${imagePath}copilot.glb`,
      scene: null,
    },
  }
  isLoaded: boolean = false

  async load(callback: {(): void; (): void}) {
    const allPromisess = [...this.loadImages(), ...this.loadGltfs()]

    try {
      await Promise.all(allPromisess)

      this.isLoaded = true

      // All assets loaded
      if (callback) callback()
    } catch (error) {
      // eslint-disable-next-line no-console
      console.log('Error loading assets', error)
    }
  }

  loadGltfs() {
    const loader = new GLTFLoader()

    const promises = Object.values(this.gltfs).map(
      gltf =>
        new Promise((resolve, reject) => {
          loader.load(
            gltf.src,
            loadedGltf => {
              gltf.scene = loadedGltf.scene
              resolve(loadedGltf.scene)
            },
            undefined,
            error => reject(error),
          )
        }),
    )

    return promises
  }

  loadImages() {
    const loader = new TextureLoader()

    const promises = Object.values(this.images).map(
      image =>
        new Promise((resolve, reject) => {
          loader.load(
            image.src,
            texture => {
              image.texture = texture
              texture.flipY = image.flipY
              if (image.encoding) texture.encoding = image.encoding
              resolve(texture)
            },
            undefined,
            error => reject(error),
          )
        }),
    )

    return promises
  }
}
